/* ---------- extra trees ---------- */
const txTreeBase = txTree;
txTree = function (kind, R) {
  if (!['gum', 'scrub', 'cypress', 'birch', 'plane'].includes(kind)) return txTreeBase(kind, R);
  const r = (kind === 'scrub' ? 12 : 18) + R() * 14, s = Math.ceil(r * 2.8), c = document.createElement('canvas'); c.width = c.height = Math.ceil(s * TX_SC);
  const g = c.getContext('2d'); g.scale(TX_SC, TX_SC); g.translate(s / 2 - 3, s / 2 - 3);
  g.fillStyle = 'rgba(5,10,8,.3)'; g.beginPath(); g.arc(r * .3, r * .42, r * (kind === 'cypress' ? .55 : 1), 0, 7); g.fill();
  const cols = { gum: ['#4f6a52', '#6e8b6c', '#a2b89a'], scrub: ['#6d6a3e', '#8d8a4f', '#b0a86c'], cypress: ['#1e3a26', '#2a5134', '#3d6b47'], birch: ['#4c7a3a', '#6e9e4e', '#a8c978'], plane: ['#3a5f2c', '#517e3c', '#7aa458'] }[kind];
  const n = kind === 'scrub' ? 3 : kind === 'cypress' ? 3 : 7, sq = kind === 'cypress' ? .5 : 1;
  for (const [i, col] of cols.entries()) { g.fillStyle = col; for (let k = 0; k < n; k++) { const a = R() * 7, q = r * (.75 - i * .22) * Math.sqrt(R()); g.beginPath(); g.ellipse(Math.cos(a) * q * sq - i * r * .1, Math.sin(a) * q - i * r * .13, r * (.42 - i * .08) * sq, r * (.42 - i * .08), 0, 0, 7); g.fill(); } }
  return { c, s };
};

